package com.example.app04.application.service; import com.example.app04.domain.entity.Booking; import com.example.app04.infrastructure.repository.BookingRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class BookingService { private final BookingRepository repository; public BookingService(BookingRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Booking> list() { return repository.findAll(); } @Transactional public Booking create(Booking e) { return repository.save(e); } }
